def query(folder, question: str, *, top_k: int = 6, ollama_url=OLLAMA_URL) -> list:
    try:
        folder = Path(folder)
        col = _get_collection(folder)
        if col is None or not question.strip():
            return []
        qvec = _embed([question], ollama_url=ollama_url)
        if not qvec:
            return []
        res = col.query(query_embeddings=qvec, n_results=top_k)
        ids = (res.get("ids") or [[]])[0]
        dists = (res.get("distances") or [[]])[0]
        out = []
        for i, name in enumerate(ids):
            dist = dists[i] if i < len(dists) else 1.0
            out.append((name, round(1.0 - float(dist), 4)))
        return out
    except Exception:
        return []

def _semantic_objects(schema: dict, question: str, schema_folder, k: int = 6) -> list:
    """Layer-5 semantic hits as schema objects, best-effort."""
    if not schema_folder:
        return []
    try:
        hits = semantic_index.query(schema_folder, question, top_k=k)
    except Exception:
        return []
    by_name = {o.get("name"): o for o in schema.get("objects", [])}
    out = []
    for name, _score in hits:
        o = by_name.get(name)
        if o is not None and not _is_junk_table(name):
            out.append(o)
    return out

PBKDF2_ITERS = 200_000  # OWASP 2023 minimum for SHA-256

def _hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, PBKDF2_ITERS)
    return f"pbkdf2_sha256${PBKDF2_ITERS}${salt.hex()}${dk.hex()}"

def _verify_password(password: str, stored: str) -> bool:
    try:
        algo, iters_s, salt_hex, hash_hex = stored.split("$")
        if algo != "pbkdf2_sha256":
            return False
        iters = int(iters_s)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(hash_hex)
        dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iters)
        return hmac.compare_digest(dk, expected)
    except Exception:
        return False

def _session_user_from_handler(handler) -> dict:
    """Return the user dict for the session cookie on this request, or None."""
    token = auth.parse_session_cookie(handler.headers.get("Cookie", ""))
    return auth.lookup_session(token) if token else None

def _resolve_permissions(handler=None) -> dict:
    try:
        mode = auth.auth_mode()
    except Exception:
        mode = "os_user"
    if mode == "login":
        user = _session_user_from_handler(handler) if handler is not None else None
        if user:
            return auth.resolve_for_user(user)
        return auth.anonymous_payload(needs_setup=not auth.has_any_user())
    # os_user mode - preserves legacy behaviour
    return auth.resolve_for_os_user()
